item.command:
/usr/bin/pwsh -NoProfile -Command '$dir='"'docs/receipts/federation/20261117-plan-definitions'
function Read-Node([string]"'$name){[Text.Json.Nodes.JsonNode]::Parse([IO.File]::ReadAllText((Resolve-Path -LiteralPath (Join-Path $dir $name))))}
function Get-CanonicalRecords([Text.Json.Nodes.JsonNode]$node){
 $sb=[Text.StringBuilder]::new()
 foreach($rec in @($node['"'records'].AsArray()) | Sort-Object { "'$_['"'id'].GetValue[string]() }){
  [void]"'$sb.Append($rec['"'id'].GetValue[string]()).Append(\""'`u{0}").Append($rec['"'kind'].GetValue[string]()).Append(\""'`u{0}").Append($rec['"'title'].GetValue[string]()).Append(\""'`u{0}").Append($rec['"'description'].GetValue[string]()).Append(\""'`u{0}")
  foreach($ac in @($rec['"'acceptanceCriteria'].AsArray()) | Sort-Object { "'$_['"'id'].GetValue[string]() }){[void]"'$sb.Append($ac['"'id'].GetValue[string]()).Append(\""'`u{0}").Append($ac['"'text'].GetValue[string]()).Append(\""'`u{0}").Append($ac['"'isSatisfied'].GetValue[bool]()).Append(\""'`u{0}")}
 }
 $sb.ToString()
}
$base=Read-Node '"'plan-requirements-final-v2.json';"'$baseCanon=Get-CanonicalRecords $base
$sha=[Security.Cryptography.SHA256]::Create()
$names=@('"'plan-requirements.json','plan-requirements-final.json','plan-requirements-final-v2.json','plan-requirements-hv-r1.json','plan-requirements-hv-r1-current.json')
